-- Initial schema (TECHNICAL_DESIGN §5.2).
-- IDs are UUIDv7 generated by the application, so no id defaults here.
-- All times are timestamptz (UTC); ranges are half-open [start, end).

CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE EXTENSION IF NOT EXISTS citext;

CREATE TABLE users (
  id             uuid PRIMARY KEY,
  email          citext       NOT NULL,
  password_hash  varchar(100),                          -- null until invite accepted
  full_name      varchar(120) NOT NULL,
  role           varchar(20)  NOT NULL,
  timezone       varchar(64)  NOT NULL DEFAULT 'UTC',   -- IANA, used for emails
  active         boolean      NOT NULL DEFAULT true,
  created_at     timestamptz  NOT NULL DEFAULT now(),
  updated_at     timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT users_email_unique UNIQUE (email),
  CONSTRAINT users_role_valid CHECK (role IN ('CUSTOMER', 'PROVIDER', 'ADMIN'))
);

CREATE TABLE providers (
  id              uuid PRIMARY KEY,
  user_id         uuid         NOT NULL,
  display_name    varchar(120) NOT NULL,
  bio             text,
  timezone        varchar(64)  NOT NULL,                -- IANA, e.g. 'Asia/Kolkata'
  buffer_minutes  int          NOT NULL DEFAULT 0,
  active          boolean      NOT NULL DEFAULT true,
  CONSTRAINT providers_user_fk FOREIGN KEY (user_id) REFERENCES users (id),
  CONSTRAINT providers_user_unique UNIQUE (user_id),
  CONSTRAINT providers_buffer_range CHECK (buffer_minutes BETWEEN 0 AND 120)
);

-- The product's "Service"; ServiceOffering in Java.
CREATE TABLE services (
  id                uuid PRIMARY KEY,
  name              varchar(120) NOT NULL,
  description       text,
  duration_minutes  int          NOT NULL,
  active            boolean      NOT NULL DEFAULT true,
  CONSTRAINT services_duration_valid
    CHECK (duration_minutes BETWEEN 5 AND 480 AND duration_minutes % 5 = 0)
);

CREATE TABLE provider_services (
  provider_id  uuid NOT NULL,
  service_id   uuid NOT NULL,
  CONSTRAINT provider_services_pk PRIMARY KEY (provider_id, service_id),
  CONSTRAINT provider_services_provider_fk FOREIGN KEY (provider_id) REFERENCES providers (id),
  CONSTRAINT provider_services_service_fk FOREIGN KEY (service_id) REFERENCES services (id)
);

CREATE TABLE availability_rules (
  id           uuid PRIMARY KEY,
  provider_id  uuid     NOT NULL,
  day_of_week  smallint NOT NULL,                       -- ISO, 1 = Monday
  start_time   time     NOT NULL,
  end_time     time     NOT NULL,
  CONSTRAINT availability_rules_provider_fk
    FOREIGN KEY (provider_id) REFERENCES providers (id) ON DELETE CASCADE,
  CONSTRAINT availability_rules_day_valid CHECK (day_of_week BETWEEN 1 AND 7),
  CONSTRAINT availability_rules_time_order CHECK (start_time < end_time)
);
CREATE INDEX availability_rules_provider_day_idx ON availability_rules (provider_id, day_of_week);

CREATE TABLE time_off (
  id           uuid PRIMARY KEY,
  provider_id  uuid        NOT NULL,
  start_at     timestamptz NOT NULL,
  end_at       timestamptz NOT NULL,
  reason       varchar(200),
  CONSTRAINT time_off_provider_fk
    FOREIGN KEY (provider_id) REFERENCES providers (id) ON DELETE CASCADE,
  CONSTRAINT time_off_range_order CHECK (start_at < end_at)
);
CREATE INDEX time_off_provider_range_idx
  ON time_off USING gist (provider_id, tstzrange(start_at, end_at, '[)'));

CREATE TABLE bookings (
  id                   uuid PRIMARY KEY,
  customer_id          uuid        NOT NULL,
  provider_id          uuid        NOT NULL,
  service_id           uuid        NOT NULL,
  start_at             timestamptz NOT NULL,
  end_at               timestamptz NOT NULL,
  blocked_until        timestamptz NOT NULL,            -- end_at + provider buffer at booking time (§5.3)
  status               varchar(20) NOT NULL,
  customer_notes       varchar(500),
  cancel_reason        varchar(500),
  cancelled_by         uuid,
  rescheduled_from_id  uuid,
  reminder_sent_at     timestamptz,
  version              bigint      NOT NULL DEFAULT 0,  -- optimistic locking
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT bookings_customer_fk FOREIGN KEY (customer_id) REFERENCES users (id),
  CONSTRAINT bookings_provider_fk FOREIGN KEY (provider_id) REFERENCES providers (id),
  CONSTRAINT bookings_service_fk FOREIGN KEY (service_id) REFERENCES services (id),
  CONSTRAINT bookings_cancelled_by_fk FOREIGN KEY (cancelled_by) REFERENCES users (id),
  CONSTRAINT bookings_rescheduled_from_fk FOREIGN KEY (rescheduled_from_id) REFERENCES bookings (id),
  CONSTRAINT bookings_status_valid
    CHECK (status IN ('CONFIRMED', 'CANCELLED', 'COMPLETED', 'NO_SHOW')),
  CONSTRAINT bookings_time_order CHECK (start_at < end_at AND end_at <= blocked_until),

  -- FR-16: a provider never has two overlapping CONFIRMED bookings (buffer included).
  -- Mapped to SLOT_TAKEN by name in Java; never remove or weaken.
  CONSTRAINT bookings_no_provider_overlap EXCLUDE USING gist (
    provider_id WITH =, tstzrange(start_at, blocked_until, '[)') WITH &&
  ) WHERE (status = 'CONFIRMED'),

  -- CUSTOMER_OVERLAP: a customer can't be in two appointments at once.
  CONSTRAINT bookings_no_customer_overlap EXCLUDE USING gist (
    customer_id WITH =, tstzrange(start_at, end_at, '[)') WITH &&
  ) WHERE (status = 'CONFIRMED')
);
CREATE INDEX bookings_customer_start_idx ON bookings (customer_id, start_at);
CREATE INDEX bookings_provider_start_idx ON bookings (provider_id, start_at);
CREATE INDEX bookings_reminder_due_idx ON bookings (start_at)
  WHERE status = 'CONFIRMED' AND reminder_sent_at IS NULL;

CREATE TABLE booking_events (
  id           uuid PRIMARY KEY,
  booking_id   uuid        NOT NULL,
  from_status  varchar(20),
  to_status    varchar(20) NOT NULL,
  actor_id     uuid,                                    -- null = system
  reason       varchar(500),
  created_at   timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT booking_events_booking_fk FOREIGN KEY (booking_id) REFERENCES bookings (id),
  CONSTRAINT booking_events_actor_fk FOREIGN KEY (actor_id) REFERENCES users (id)
);
CREATE INDEX booking_events_booking_idx ON booking_events (booking_id, created_at);

CREATE TABLE email_outbox (
  id               uuid PRIMARY KEY,
  template         varchar(50)  NOT NULL,               -- e.g. BOOKING_CONFIRMED_CUSTOMER
  recipient        varchar(254) NOT NULL,
  payload          jsonb        NOT NULL,               -- template variables snapshot
  booking_id       uuid,
  status           varchar(10)  NOT NULL DEFAULT 'PENDING',
  attempts         int          NOT NULL DEFAULT 0,
  next_attempt_at  timestamptz  NOT NULL DEFAULT now(),
  last_error       text,
  created_at       timestamptz  NOT NULL DEFAULT now(),
  sent_at          timestamptz,
  CONSTRAINT email_outbox_booking_fk FOREIGN KEY (booking_id) REFERENCES bookings (id),
  CONSTRAINT email_outbox_status_valid CHECK (status IN ('PENDING', 'SENT', 'FAILED'))
);
CREATE INDEX email_outbox_pending_idx ON email_outbox (next_attempt_at) WHERE status = 'PENDING';

CREATE TABLE refresh_tokens (
  id           uuid PRIMARY KEY,
  user_id      uuid        NOT NULL,
  token_hash   char(64)    NOT NULL,                    -- SHA-256 of the opaque token
  expires_at   timestamptz NOT NULL,
  revoked_at   timestamptz,
  replaced_by  uuid,
  CONSTRAINT refresh_tokens_user_fk FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT refresh_tokens_replaced_by_fk FOREIGN KEY (replaced_by) REFERENCES refresh_tokens (id),
  CONSTRAINT refresh_tokens_hash_unique UNIQUE (token_hash)
);

-- Invites and password resets.
CREATE TABLE user_tokens (
  id          uuid PRIMARY KEY,
  user_id     uuid        NOT NULL,
  type        varchar(20) NOT NULL,
  token_hash  char(64)    NOT NULL,
  expires_at  timestamptz NOT NULL,
  used_at     timestamptz,
  CONSTRAINT user_tokens_user_fk FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT user_tokens_hash_unique UNIQUE (token_hash),
  CONSTRAINT user_tokens_type_valid CHECK (type IN ('INVITE', 'PASSWORD_RESET'))
);

CREATE TABLE settings (
  key         varchar(60)  PRIMARY KEY,
  value       varchar(200) NOT NULL,
  updated_at  timestamptz  NOT NULL DEFAULT now()
);
